// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address caller) internal {
        vm.assume(true);
        bool reverted;
        try c.newEmergencyOracle("desc") { reverted = false; } catch { reverted = true; }
        address team;
        try c.jojoTeam() returns (address __r) { team = __r; } catch { return; }
        assertTrue(reverted == (address(this) != team));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
